// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new C();
    }

    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Ensure the value is bounded to avoid excessive gas
        value = bound(value, 0, address(c).balance);

        // Call sendMoney via the deployer (onlyOwner)
        vm.prank(deployer);
        c.sendMoney(target, value, data);

        // The owner must always equal the deployer (the original msg.sender of the constructor)
        assertTrue(c.owner() == deployer);
    }
}

